import pandas as pd


def _plan_eq(a, b):
    a_na = pd.isna(a)
    b_na = pd.isna(b)
    if a_na and b_na:
        return True
    if a_na != b_na:
        return False
    return a == b


def run(inputs: dict) -> dict:
    dim = inputs["dim_account"].copy()
    stg = inputs["stg_account"].copy()

    # Build per-account mutable list of version dicts from existing dim table.
    accounts = {}
    for _, row in dim.iterrows():
        aid = row["account_id"]
        accounts.setdefault(aid, []).append(
            {
                "plan": row["plan"],
                "eff_start_date": row["eff_start_date"],
                "eff_end_date": row["eff_end_date"],
                "is_current": row["is_current"],
            }
        )

    # Process staged records in order: account_id, update_date ASC (stable sort
    # preserves original relative order on ties).
    stg_sorted = stg.sort_values(
        ["account_id", "update_date"], kind="mergesort"
    ).reset_index(drop=True)

    for _, s in stg_sorted.iterrows():
        aid = s["account_id"]
        plan = s["plan"]
        ud = s["update_date"]

        versions = accounts.setdefault(aid, [])

        if len(versions) == 0:
            versions.append(
                {
                    "plan": plan,
                    "eff_start_date": ud,
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                }
            )
            continue

        # Find the version covering update_date: start <= ud < end (end NULL = open).
        v = None
        for ver in versions:
            start = ver["eff_start_date"]
            end = ver["eff_end_date"]
            if start <= ud and (pd.isna(end) or ud < end):
                v = ver
                break

        if v is None:
            # update_date is earlier than the account's earliest version.
            f = min(versions, key=lambda x: x["eff_start_date"])
            versions.append(
                {
                    "plan": plan,
                    "eff_start_date": ud,
                    "eff_end_date": f["eff_start_date"],
                    "is_current": 0,
                }
            )
        else:
            if _plan_eq(v["plan"], plan):
                # no-op, unchanged attribute
                pass
            elif ud == v["eff_start_date"]:
                # same-day correction, no new version
                v["plan"] = plan
            else:
                # split v at update_date
                versions.append(
                    {
                        "plan": plan,
                        "eff_start_date": ud,
                        "eff_end_date": v["eff_end_date"],
                        "is_current": v["is_current"],
                    }
                )
                v["eff_end_date"] = ud
                v["is_current"] = 0

    rows = []
    for aid, versions in accounts.items():
        for ver in versions:
            rows.append(
                {
                    "account_id": aid,
                    "plan": ver["plan"],
                    "eff_start_date": ver["eff_start_date"],
                    "eff_end_date": ver["eff_end_date"],
                    "is_current": ver["is_current"],
                }
            )

    out = pd.DataFrame(
        rows,
        columns=["account_id", "plan", "eff_start_date", "eff_end_date", "is_current"],
    )

    if len(out) > 0:
        out = out.sort_values(
            ["account_id", "eff_start_date"], kind="mergesort"
        ).reset_index(drop=True)
        out["account_id"] = out["account_id"].astype("int64")
        out["is_current"] = out["is_current"].astype("int64")
        out["eff_start_date"] = pd.to_datetime(out["eff_start_date"])
        out["eff_end_date"] = pd.to_datetime(out["eff_end_date"])
    else:
        out = pd.DataFrame(
            {
                "account_id": pd.Series(dtype="int64"),
                "plan": pd.Series(dtype="object"),
                "eff_start_date": pd.Series(dtype="datetime64[us]"),
                "eff_end_date": pd.Series(dtype="datetime64[us]"),
                "is_current": pd.Series(dtype="int64"),
            }
        )

    return {"dim_account_out": out}
